// Resuelve SKU -> price con el inventario, y decide si alcanza el stock.
const pedido = $('Webhook · apartar').first().json.body;
const sku = (pedido.sku || '').trim();
const cantidad = Number(pedido.cantidad || 1);
const inv = $input.first().json.inventory || [];
const i = inv.find(x => (x.sku || '').trim() === sku);
if (!i) return [{ json: { ok: false, motivo: 'sku_no_existe', sku, cantidad } }];
const disponible = Number(i.availableQuantity ?? 0);
const alcanza = disponible >= cantidad;
return [{ json: { productId: i.product, priceId: i._id, nombre: i.productName, disponible, sku, cantidad, alcanza,
  nuevoStock: disponible - cantidad, ok: alcanza, motivo: alcanza ? null : 'agotado' } }];

// El reloj del apartado. expira_en va en ISO 8601 CON OFFSET, siempre.
// N2 lo compara contra la hora actual y SP02 tiene que escribirlo igual.
const datos = $('Resolver SKU y stock').first().json;
const contactId = $('Webhook · apartar').first().json.body.contactId;
const horas = Number($env.HORAS_APARTADO || 24);
const expira = new Date(Date.now() + horas * 3600 * 1000);

return [{ json: {
  ok: true,
  sku: datos.sku,
  articulo: datos.nombre,
  cantidad: datos.cantidad,
  productId: datos.productId,
  priceId: datos.priceId,
  monto: Number($('GHL · leer precio').first().json.amount ?? 0),
  contactId,
  stockRestante: datos.nuevoStock,
  expira_en: expira.toISOString(),
  // Para que el bot lo diga tal cual y no convierta fechas.
  expira_texto: expira.toLocaleString('es-MX', { timeZone: 'America/Chicago', weekday: 'long', day: 'numeric', month: 'long', hour: 'numeric', minute: '2-digit' })
} }];

